do $$ declare sid uuid := (select id from school where slug = 'llds'); r_store uuid; r_lille uuid; t uuid; p uuid; tr uuid; rule uuid; d date; begin
select id into r_store from room where school_id = sid and name = 'Store Sal'; select id into r_lille from room where school_id = sid and name = 'Lille Sal';
update team set description = 'Mini Cuties er et showdance-hold for børn, både begyndere og børn med lidt danseerfaring, herunder tidligere konkurrencesæsoner. Undervisningen kombinerer dans og leg med grundlæggende showdance-teknik samt både store og små koreografier og opvisninger.

Velkommen til Mini Cuties
Mini Cuties er et showdance-hold for børn, der passer til begyndere og børn med lidt danseerfaring, herunder tidligere konkurrencesæsoner. Timerne kombinerer dans og leg med grundlæggende showdance-teknik og både store og små koreografier og opvisninger. Det er helt frivilligt at deltage i konkurrencer.', price = '2.400 kr. for hel sæson, eller 1.750 kr. for halv sæson (august–december)', years = '2017–2020', day_time = 'Mandag kl. 16:00–16:45 (45 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2026/04/1X4A4179-c-477x1024.jpg') where school_id = sid and name = 'Mini Cuties';
update team set description = 'Mini Hip Hop – Seje trin & store smil! Et hip hop-hold for de yngste på alle niveauer, fra begyndere til mere erfarne. Der arbejdes med rytme, balance og koordination i et legende og opmuntrende miljø, hvor sjov, venskab og danseglæde er i fokus.

Mini Hip Hop – Seje Trin & Store Smil!
Holdet er for små børn på alle niveauer, fra begyndere til mere erfarne dansere. Der arbejdes med rytme, balance og koordination i et legende og opmuntrende miljø. Fokus er på sjov, venskab og glæden ved at danse.', price = '2.250 kr. for hel sæson, eller 1.550 kr. for halv sæson (august–december)', years = '2017–2020', day_time = 'Mandag kl. 16:50–17:35 (45 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2025/04/DSC_1096.jpg') where school_id = sid and name = 'Hip Hop Mini';
update team set description = 'Shining Stars er holdet for børn, der tager deres første skridt ind i dansens verden. Et begynderhold fyldt med energi, sjov og bevægelse, som passer til børn, der aldrig har danset før, eller som lige er begyndt.

Shining Stars – Hvor danseglæden begynder!
Her lærer børnene i eget tempo og opdager glæden ved musik og bevægelse. Vi danser, leger og bygger tryghed op, så alle kan føle sig som stjerner på dansegulvet. På holdet arbejder vi med: Grundlæggende dansetrin og rytme. Små, sjove koreografier. Leg og bevægelse, så alle kan være med. Et positivt fællesskab med plads til grin, venskaber og udvikling. Mulighed for at deltage i konkurrencer – helt frivilligt (konkurrencekalenderen findes længere nede på siden). Shining Stars er stedet, hvor danseeventyret begynder, og hvor hvert barn får lov til at skinne. Velkommen til alle nye små stjerner!', price = '2.400 kr. for hel sæson, eller 1.750 kr. for halv sæson (august–december)', years = '2014–2016', day_time = 'Mandag kl. 17:40–18:25 (45 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2026/04/DSC04306-769x1024.jpg') where school_id = sid and name = 'Shining Stars';
update team set description = 'Et hold for dansere, der vil udforske en mere udtryksfuld og kunstnerisk dansestil, hvor bevægelse, følelser og fortælling hænger sammen. Holdet er for både nybegyndere og dem, der har danset før.

Velkommen til Contemporary - Børn & junior
Holdet er for dansere, der vil udforske en mere udtryksfuld og kunstnerisk dansestil, hvor bevægelse, følelser og fortælling hænger sammen. Holdet er for både nybegyndere og dem, der har danset før.

Contemporary – Dans med følelse, flow og fordybelse
Contemporary er en blanding af ballet, moderne dans og jazz, der giver en fri, flydende og kraftfuld stil, hvor hele kroppen tages i brug. På holdet arbejder vi med: Grundlæggende teknik og bevægelseskvalitet. Flow og dynamik i koreografi. Improvisation og følelsesmæssigt udtryk. Kropskontrol, balance og styrke. Undervisningen tilpasses, så alle niveauer kan deltage. Det vigtigste er lysten til at mærke musikken og bevæge sig på en ny måde.', price = '2.250 kr. for hel sæson, eller 1.550 kr. for halv sæson (august–december)', years = '2008–2015', day_time = 'Mandag kl. 18:30–19:15 (45 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2024/04/DSC01616-1-scaled.jpg') where school_id = sid and name = 'Contemporary Begynder';
update team set description = 'Et hold for dansere, der allerede har erfaring med contemporary eller beslægtede stilarter og vil udvikle sig teknisk og kunstnerisk. Her lægges vægt på intensitet, udtryk og teknisk præcision.

Velkommen til Contemporary - Børn, junior & voksen
Holdet er for dansere, der allerede har erfaring med contemporary eller beslægtede stilarter og vil udvikle sig teknisk og kunstnerisk.

Contemporary Øvet+ & Elite – For dig, der vil fordybe dig i dansens kunst
Holdet lægger vægt på intensitet, udtryk og teknisk præcision. Danserne lærer at forstå og formidle følelser gennem bevægelse. Der arbejdes med dybdegående koreografier, improvisation og performance, og hver danser hjælpes til et stærkt, personligt udtryk. På holdet arbejder vi med: Avanceret contemporary-teknik og gulvarbejde. Dynamisk bevægelseskvalitet og linjer. Fortælling, følelsesmæssigt udtryk og musikalitet. Improvisation og kreativt arbejde. Performance og scenepræsentation.

Hvem er holdet for?
Holdet henvender sig til øvede+ og elitedansere, som vil arbejde målrettet og gå i dybden med detaljerne. Fællesskabet er trygt, engageret og seriøst, og alle aldre danser sammen. Danserne løfter hinanden teknisk og inspirerer hinanden kreativt. Dans handler ikke kun om at bevæge sig – men om at mærke og berøre med sin bevægelse.', price = '2.250 kr. for hel sæson, eller 1.550 kr. for halv sæson (august–december)', years = 'Fra årgang 2016', day_time = 'Mandag kl. 19:20–20:05 (45 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2025/04/DSC01723-scaled.jpg') where school_id = sid and name = 'Contemporary Elite';
update team set description = 'Hip Hop Øvet+ / Elite – Fokus, power og performance på højeste niveau. Holdet er for dansere, der elsker hip hop og vil udvikle deres dans. Der forventes erfaring med dans og koreografi samt evnen til at lære hurtigt, arbejde detaljeret og performe med udtryk og intensitet.

Hip Hop Øvet+ / Elite – Fokus, power og performance på højeste niveau
Holdet henvender sig til dansere, der elsker hip hop og vil udvikle deres dans. Der forventes erfaring med dans og koreografi samt evnen til at lære hurtigt, arbejde detaljeret og performe med udtryk og intensitet. Der stilles høje krav til teknik, energi og indstilling i et motiverende, støttende og ambitiøst miljø, hvor der også er plads til at have det sjovt.

På holdet arbejder vi med:
Avanceret koreografi med fokus på skarpe detaljer og musikalitet. Freestyle og personlig stil, så du står stærkt i dit eget udtryk. Stamina og præcision, så du kan performe med power og kontrol. Performance og sceneudtryk med træning til opvisninger og konkurrencer. Holdet arbejder målrettet mod shows og forventer dedikation, tilstedeværelse og vilje til at udvikle sig – både teknisk og kunstnerisk. Er du klar til at nørde dans og give alt, hvad du har? Så er dette holdet for dig.', price = '2.250 kr. for hel sæson, eller 1.550 kr. for halv sæson (august–december)', years = 'Fra årgang 2012', day_time = 'Mandag kl. 20:10–20:55 (45 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2025/04/DSC_1096.jpg') where school_id = sid and name = 'Hip Hop Junior & Voksen Elite';
update team set description = 'Tricks & Spring for seje børn. Holdet er for børn, der elsker at lave tricks og spring og vil udfordre sig selv. Der arbejdes med grundlæggende springteknik og gulvtricks i et trygt og sjovt fællesskab – uanset om du har prøvet det før eller ej.

Tricks & Spring for Seje Børn
Holdet er for børn, der gerne vil lave tricks og spring og udfordre sig selv. Her arbejder vi med grundlæggende springteknik og lærer gulvtricks i et trygt og sjovt fællesskab, uanset om du har prøvet det før. Vi træner på airtrack og gulv – blandt andet rul, vejrmøller, håndstand og back over. Der er også styrketræning, især for arme og core, så børnene bliver mere sikre og modige i bevægelserne. Holdet er for alle niveauer, og der kræves ingen forkundskaber.', price = '2.250 kr. for hel sæson, eller 1.550 kr. for halv sæson (august–december)', years = '2014–2016', day_time = 'Mandag kl. 16:30–17:15 (45 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2025/04/DSC09446-scaled.jpg') where school_id = sid and name = 'Spring & Tumbling Børn';
update team set description = 'Power, rytme og personlig stil! Holdet er for dig, der vil danse til tunge beats, lære koreografier og udvikle din egen stil. Undervisningen tilpasses, uanset om du er begynder, let øvet eller øvet.', price = '2.250 kr. for hel sæson, eller 1.550 kr. for halv sæson (august–december)', years = 'Fra årgang 2016', day_time = 'Mandag kl. 18:25–19:10 (45 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2025/04/DSC_3195.jpg') where school_id = sid and name = 'Hip Hop Junior & Voksen Begynder';
update team set description = 'Control er holdet for dansere, der vil det helt seriøst. Niveauet er højt fra start, og der forventes godt kendskab til koreografi, teknik og performance – samt lysten til at blive udfordret.

Vigtigt at vide
Træneren vurderer inden for de første 4 undervisningsgange, om niveauet passer til den enkelte danser. Hvis det ikke passer, får du besked, og betalingen refunderes, så du kan vælge et andet hold. Ved tilmelding accepterer du, at denne vurdering kan finde sted.

På Control
Træner vi på højt niveau med fokus på detaljer, udtryk og præcision. Bliver du en del af et seriøst miljø med ambitiøse dansere. Forventes deltagelse i turneringer og ekstra træninger. Går engagement og ansvar hånd i hånd med fællesskab og glæde. Control er for dem, der tager dansen seriøst og giver alt ved hver træning. Er du klar til at tage kontrollen over din udvikling?

Prøvetid og pris ved tilmelding
Ved tilmelding eller fremmøde til første træning accepterer du, at du kan blive flyttet til Empire, hvis træneren vurderer, at det er det rette niveau. Derfor er prisen ved tilmelding den samme som på Empire. Efter de 4 prøvegange betaler de dansere, der fortsætter på Control, de resterende 975 kr.', price = '6.800 kr. for hele sæsonen (tilmelding til Empire-pris; resterende 975 kr. betales efter 4 prøvegange)', years = '2008–2013', day_time = 'Mandag kl. 19:10–20:10 (60 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2026/04/1X4A3732-c-scaled.jpg') where school_id = sid and name = 'Control';
update team set description = 'Mini Angels – vores stærkeste Mini Børn-hold. Et øvet+ hold for de mest engagerede og talentfulde Mini Børn-dansere, som gerne vil udfordres teknisk og kreativt.

Mini Angels – Vores stærkeste Mini Børn-hold
Mini Angels er et øvet+ hold for de mest engagerede og talentfulde Mini Børn-dansere, som gerne vil udfordres teknisk og kreativt. På holdet arbejder vi med: Styrket teknik og kropskontrol, hvor spring, drej og bevægelser forfines. Udtryk og performance, så danserne lærer at stå stærkt på scenen. Fællesskab og glæde, hvor holdet hepper på hinanden og udvikler sig som team. Forberedelse til turneringer med koreografier og målrettet træning til opvisninger og konkurrencer. Mini Angels er for dansere, der vil lidt mere og har lyst til at udvikle sig og have det sjovt sammen.

OBS: Audition
Man skal til audition for at blive en del af Mini Angels. Tid og sted for audition findes på forsiden af hjemmesiden.

Tekniktræning
Torsdag kl. 15:45–16:30 med træner Christine. Et ekstra teknikhold, der fokuserer på at slibe de tekniske færdigheder, arbejde med avancerede spring, drejninger og tricks og styrke de små muskler. Formålet er at løfte dansepræstationerne og mindske risikoen for skader. Teknikholdet er inkluderet i prisen.', price = '5.450 kr. for hele sæsonen', years = '2017–2020', day_time = 'Tirsdag kl. 15:40–16:40 (60 min)', closed = true, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2026/04/1X4A2209-2-c-2-502x1024.jpg') where school_id = sid and name = 'Mini Angels';
update team set description = 'The AXIS – vores højeste Elite+ Junior 2-hold. Holdet er for de mest dedikerede juniordansere i junior 2-rækken, som vil arbejde målrettet med deres dans. Et Elite+-hold med høje krav, men også store udviklingsmuligheder som danser og performer.

På The AXIS træner vi intenst og fokuseret med:
Fast træning: 1 time og 45 minutter om ugen med fokus på koreografi, performance og udtryk. Styrketræning: 45 minutter målrettet styrke for at mindske skaderisiko. Tekniktime: 1 time og 15 minutter med teknik, drejninger, spring og kropskontrol.

Forventninger
Du skal være klar til at yde dit bedste hver gang. I løbet af sæsonen gives der ''lektier'' i form af små opgaver og tekniske mål, for eksempel at mestre bestemte tricks eller styrkeøvelser. Holdet er et dedikeret fællesskab, hvor man løfter hinanden og går all in på dansen. Her vælger man at ville det allerhøjeste. Man skal til audition for at blive en del af holdet. Krav og regelhæfte findes som PDF på siden.

Styrketræning & Skadesforebyggelse
Tirsdag kl. 18:30–19:15 med Line Lund Olesen. Timen er obligatorisk og inkluderet i prisen. Deltagelse er et krav for at være på holdet.', price = '11.450 kr. for hele sæsonen', years = '2008–2011', day_time = 'Tirsdag kl. 16:45–18:30 (1 time 45 min)', closed = true, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2026/04/1X4A2433-c-kopi-580x1024.jpg') where school_id = sid and name = 'The AXIS';
update team set description = 'Holdet er for dig, der vil løfte din styrke til et højere niveau og lære, hvordan styrketræning kan forbedre både din dans og dit generelle velvære.

Styrkehold for junior og voksne (op til 21 år)
Målgruppen er junior- og voksendansere op til 21 år.', price = '2.250 kr. for hel sæson, eller 1.550 kr. for halv sæson (august–december)', years = '2004–2013', day_time = 'Tirsdag kl. 18:30–19:15 (45 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2025/04/DSC00124-kopi-1-scaled.jpg') where school_id = sid and name = 'Styrketræning Junior & Voksen';
update team set description = 'Apexion – vores Elite+ Junior 1 hold. Et hold for ambitiøse juniordansere i junior 1-rækken, der vil udvikle sig og tage dansen til næste niveau med målrettet arbejde med teknik, performance og sammenhold.

Apexion – Vores Elite+ Junior 1 Hold
Apexion er et Elite+-hold for ambitiøse juniordansere i junior 1-rækken, der vil udvikle sig og tage dansen til næste niveau. Holdet arbejder målrettet med teknik, performance og sammenhold. Vi træner struktureret og fokuseret i tre dele: Fast træning – 1 time og 30 minutter om ugen med fokus på koreografi, performance og udtryk. Styrketræning – 45 minutters målrettet træning for styrke, stabilitet og skadesforebyggelse. Tekniktime – 1 time og 15 minutter med fokus på grundteknik, drejninger, spring og kropskontrol.

Forventninger
Man skal til audition for at blive en del af Apexion og være klar til seriøst arbejde med sin udvikling. Danserne forventes at møde op med fokus, engagement og lyst til at blive bedre. Undervejs i sæsonen er der mindre opgaver og tekniske mål, der skal hjælpe den enkelte danser videre – både individuelt og som hold. Krav for Apexion og regelhæfte findes som PDF på siden.

Styrketræning & Skadesforebyggelse
Tirsdag kl. 18:30–19:15 med Line Lund Olesen. Timen er obligatorisk og inkluderet i prisen. Kan man ikke deltage, kan man ikke være med på holdet.', price = '10.950 kr. for hele sæsonen', years = '2012–2013', day_time = 'Tirsdag kl. 19:15–20:45 (1 time 30 min)', closed = true, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2026/04/1X4A6130-c-kopi-566x1024.jpg') where school_id = sid and name = 'Apexion';
update team set description = 'Disco og Disco Slow Begynder – fart, energi og kontraster! Et hold for dig, der vil prøve disco og få det bedste fra to stilarter: energi, højt tempo og flotte moves.

Disco og Disco Slow Begynder – Fart, energi og kontraster!
Holdet byder på energi, højt tempo og flotte moves for dem, der vil prøve disco – og du får det bedste fra to stilarter. Disco: Hurtig og kraftfuld dans til energisk musik, med udtryk, hurtige bevægelser og fuld fart. Disco Slow: Bygger på de samme grundtrin, men danses til roligere musik med fokus på kontrol, balance og teknik. Du lærer små serier og dansekombinationer, så du hurtigt kan være med. Der danses både solo og sammen med andre, og tempo, teknik og udtryk trænes. Holdet er åbent for alle, uanset niveau og erfaring. Kom med og få masser af danseglæde!', price = '2.250 kr. for hel sæson, eller 1.550 kr. for halv sæson (august–december)', years = '2008–2019', day_time = 'Tirsdag kl. 15:45–16:30 (45 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2025/04/DSC_0909-kopi-1.jpg') where school_id = sid and name = 'Disco Dance';
update team set description = 'Satellite Stars – når dansen begynder at tage fart! Vores øvede børnehold i showdance for børn, der allerede har en sæson bag sig og har prøvet at deltage i turneringer.

Satellite Stars – Når dansen begynder at tage fart!
Satellite Stars er vores øvede børnehold i showdance. Holdet er for børn, der allerede har en sæson bag sig og har prøvet at deltage i turneringer. Her bygger vi videre på de grundlæggende teknikker og arbejder mere med koreografi, udtryk og performance. Fokus er på udvikling og turneringer, men der er altid plads til grin, venskaber og glæde ved dansen. På holdet får du: Træning af teknik og koreografi på øvet niveau. Arbejde med udtryk, energi og scenetilstedeværelse. Deltagelse i turneringer, hvor alle er velkomne til at være med. Et trygt fællesskab med sjov og støtte. Gensidig motivation og fejring af både små og store fremskridt. Holdet er for børn, der gerne vil lidt mere – både med dansen og fællesskabet. Se turneringskalenderen længere nede på siden.

Tekniktræning
Mandag med træner Karoline Hoe. Teknikholdet fokuserer på at finpudse de tekniske færdigheder, arbejde med avancerede spring, drejninger og tricks samt styrke de små muskler for at forbedre præstationer og reducere skadesrisiko. Satellite Stars og Sky Stars træner sammen. Teknikholdet er inkluderet i prisen.', price = '5.825 kr. for hele sæsonen', years = '2014–2016', day_time = 'Tirsdag kl. 16:35–17:35 (60 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2026/04/1X4A7638-c-454x1024.jpg') where school_id = sid and name = 'Satellite Stars';
update team set description = 'New Age er vores elitehold for børn, der vil danse med styrke, præcision og personlighed. Holdet samler de dygtigste og mest engagerede børnedansere, som er klar til at give alt – både til træning og på scenen.

New Age – Elitehold for talentfulde børnedansere
New Age er elitehold for børn, der vil danse med styrke, præcision og personlighed. Holdet samler de dygtigste og mest engagerede børnedansere, som er klar til at yde fuldt output i træning og på scenen. Vi arbejder med: Avanceret koreografi – serier, der kræver styrke, timing og udtryk. Teknisk træning – fokus på spring, drejninger og kropskontrol. Scenetræning – forberedelse til turneringer, og at optræde med selvtillid og attitude. Fællesskab og fokus – holdet støtter hinanden i både med- og modgang. Det forventes, at du har solid danseerfaring og lyst til at blive bedre, er mødestabil og kan deltage i turneringer, og er motiveret for at blive udfordret sammen med andre dygtige dansere. New Age er for dem, der er klar til næste skridt som danser – med disciplin, glæde og store ambitioner.

Audition
Man skal til audition for at komme på holdet. Tid og sted står på forsiden. Krav for New Age og regelhæfte findes som PDF på siden.

Tekniktræning
Mandag kl. 15:30–16:30 med træner Seline Jepsen. Holdet arbejder med at finpudse teknik, avancerede spring, drejninger og tricks samt styrkeøvelser for de små muskler, for at forbedre præstationen og mindske skaderisikoen. Teknikholdet er inkluderet i prisen.', price = '8.100 kr. for hele sæsonen', years = '2014–2016', day_time = 'Onsdag kl. 15:30–16:45 (1 time 15 min)', closed = true, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2026/04/1X4A6562-c-2-608x1024.jpg') where school_id = sid and name = 'New Age';
update team set description = 'Mini Stjernetrin – for de allermindste dansestjerner. Et kærligt og sanseligt danseunivers for børn fra 0 til 2 år, som deltager sammen med mor eller far.

Mini Stjernetrin – for de allermindste dansestjerner
Holdet er et kærligt og sanseligt danseunivers for børn fra 0 til 2 år, som deltager sammen med mor eller far. Formålet er ikke at lære koreografi – det handler om at bevæge sig sammen, styrke båndet mellem barn og forælder og opleve glæden ved musik og rytme. Der danses og leges med enkle redskaber som tørklæder og bolde. Tempoet er roligt, så både store og små kan være med. Holdet styrker barnets motorik, balance og kropsforståelse og giver tid til nærvær, grin og musikalsk glæde. En hyggelig og sanselig stund fyldt med bevægelse, stjernedrys og smil – for dig og din lille dansemakker.', price = '1.550 kr. for hel sæson, eller 875 kr. for halv sæson (august–december)', years = '0 til og med 3 år', day_time = 'Onsdag kl. 16:45–17:15 (30 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2025/07/Skaermbillede-2025-07-05-kl.-22.32.25.jpg') where school_id = sid and name = 'Mini Stjernetrin';
update team set description = 'Øvet & Elite Disco – fart, fællesskab og fuld fokus! Holdet er for dansere, der allerede kender disco og vil udvikle sig yderligere, i et fællesskab på tværs af alder, hvor store og små hjælper hinanden.

Øvet & Elite Disco – Fart, fællesskab og fuld fokus!
Holdet henvender sig til dansere, der allerede kender disco og vil udvikle sig yderligere. Der er fællesskab på tværs af alder, hvor de store og små hjælper hinanden med venskaber og dansefaglig udvikling. Der arbejdes målrettet med teknik, spring og koreografier. Du udvikler dig både solo og i duo, lærer at optræde med selvtillid og energi og bliver en del af et trygt, sjovt og motiverende miljø. Træningen foregår med smil på læben, og vi glæder os til at se jer både til træning og på scenen.', price = '2.575 kr. for hele sæsonen', years = '2004–2015', day_time = 'Onsdag kl. 17:15–18:15 (60 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2025/04/DSC_0977.jpg') where school_id = sid and name = 'Disco';
update team set description = 'Disco Slow – styrke, følelse og smukke bevægelser. Disco danset i et langsommere, mere kontrolleret tempo til blød, stemningsfuld musik med fokus på teknik, balance og udtryk.

Disco Slow – Styrke, følelse og smukke bevægelser
Disco Slow er en dansestil, hvor disco danses i et langsommere, mere kontrolleret tempo med følelse. Der danses til blød, stemningsfuld musik, og fokus er på teknik, balance og udtryk. Holdet er for dem, der allerede kender disco. Her handler det om at mærke musikken, forfine bevægelserne og finde ro i dansen uden at miste disco-energien. På holdet: Træner vi langsomme, smukke bevægelser og stærk teknik. Skaber vi et trygt og støttende fællesskab, hvor alle har plads. Danser vi serier og små koreografier med fokus på udtryk. Holdet er for dig, der holder af musik med følelse og dans med dybde, og som gerne vil prøve en mere elegant side af disco.', price = '2.575 kr. for hele sæsonen', years = '2004–2015', day_time = 'Onsdag kl. 18:15–19:15 (60 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2025/04/DSC_1048.jpg') where school_id = sid and name = 'Disco Slow';
update team set description = 'Airy – udviklingshold for Junior 1 & 2. Holdet er for dansere, der elsker at danse og vil udvikle sig i et motiverende og støttende fællesskab, hvor glæden ved at danse står i centrum.

Airy – Udviklingshold for Junior 1 & 2
Airy er det andet hold i juniorrækken for Junior 1 og 2. Det passer til dansere, der elsker at danse og vil udvikle sig i et motiverende og støttende fællesskab. Holdet styrker de grundlæggende færdigheder og selvtilliden hos danseren, og glæden ved at danse står i centrum. Fokusområder: Udtryk og performance – at turde fylde rummet og formidle koreografi med personlighed. Teknisk udvikling – grundteknik, kropskontrol og bevægelser, så danseren bliver tryggere i sin dans. Fællesskab og holdånd – gensidig støtte og et trygt miljø, hvor alle kan udvikle sig.

Forventninger
Deltagerne forventes at have lyst til at udvikle sig og lære nyt, at deltage aktivt i træninger og turneringer og at bidrage positivt til holdets energi og sammenhold. Airy handler om udvikling, danseglæde og fællesskab – med plads til at vokse og have det sjovt.

Tekniktræning
Torsdag kl. 19:55–20:10 (angivet på siden) med træner Isabella Eriksen. Teknikholdet fokuserer på at forfine tekniske færdigheder, avancerede spring, drejninger og tricks samt styrkeøvelser for de små muskler, der kan mindske skadesrisikoen. Teknikholdet er inkluderet i prisen og afholdes sammen med Apexion.', price = '8.500 kr. for hele sæsonen', years = '2008–2013', day_time = 'Onsdag kl. 19:55–20:15 (angivet som 1 time 15 min)', closed = true, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2026/04/DSC06757-555x1024.jpg') where school_id = sid and name = 'Airy';
update team set description = 'Sky Stars er vores øvet+ børnehold i showdance for dansere, der vil arbejde seriøst med deres udvikling. Niveauet er højt fra start, og du skal være klar til at blive udfordret både teknisk og performancemæssigt.

Velkommen til Sky Stars
Sky Stars er vores øvet+-børnehold i showdance for dansere, der vil arbejde seriøst med deres udvikling. Niveauet er højt fra start, og man skal være klar til at blive udfordret både teknisk og performancemæssigt. Holdet passer også til dem, der har brug for en pause fra eliteholdene, men stadig vil fastholde niveauet.

Sky Stars – For de børn, der vil mere end bare danse
Når du er med på Sky Stars, vælger du dansen til. Du prioriterer træningerne, møder op med motivation og vilje og er klar til at give den gas hver gang. Er du klar til at give alt? Så er det her, du hører til.

Vigtigt at vide
Træneren vurderer inden for de første 4 undervisningsgange, om niveauet passer til den enkelte danser. Hvis det ikke er det rette match, får du besked, og betalingen refunderes, så du kan tilmelde dig et andet hold. Ved tilmelding accepterer du, at vurderingen kan finde sted. Ved tilmelding eller fremmøde til første træning accepterer du, at du kan flyttes til Satellite Stars, hvis træneren vurderer, at det er det rette niveau. Derfor er prisen ved tilmelding den samme som på Satellite Stars. Efter de 4 prøvegange betaler de, der fortsætter på Sky Stars, resterende 975 kr.', price = '6.800 kr. for hele sæsonen (tilmelding til Satellite Stars-pris; resterende 975 kr. betales efter 4 prøvegange)', years = '2014–2016', day_time = 'Onsdag kl. 15:45–16:45 (60 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2026/04/1X4A2112-c-scaled.jpg') where school_id = sid and name = 'Sky Stars';
update team set description = 'Styrketræning for små dansere med store drømme. Holdet hjælper børn med at opbygge den styrke, de skal bruge for at kunne de tricks og bevægelser, de drømmer om.

Styrketræning for Små Dansere med Store Drømme
Holdet hjælper børn med at blive stærkere, så de kan mestre de bevægelser, de drømmer om at udføre. Vi fokuserer på: Stærke arme – børnene lærer at holde armene strakte, så dansen får elegante linjer. Kropskontrol – børnene lærer at spænde op i kernen for at få stabilitet og balance. Optimal vejrtrækning – børnene lærer at trække vejret rigtigt, så musklerne får nok ilt, og de undgår at blive sure i musklerne. Holdet kombinerer styrke, teknik og kropsbevidsthed og giver et godt fundament for dansen. Det skal være sjovt, udfordrende og motiverende.', price = '2.250 kr. for hel sæson, eller 1.550 kr. for halv sæson (august–december)', years = '2014–2016', day_time = 'Onsdag kl. 16:50–17:35 (45 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2025/04/DSC00091-1-scaled.jpg') where school_id = sid and name = 'Styrketræning Børn';
update team set description = 'Empire – for de unge dansere med power og passion! Et begynder- og let øvet juniorhold i showdance for dansere, der allerede har en sæson bag sig og har prøvet turneringer, eller som gerne vil prøve det.

Empire – For de unge dansere med power og passion!
Empire er et begynder- og let øvet juniorhold i showdance. Holdet er til dansere, der allerede har en sæson bag sig og har prøvet turneringer, eller som gerne vil prøve det. Holdet bygger videre på erfaringen og løfter dansen med fokus på teknik, udtryk og stærke koreografier. Vi forventer, at du vil udvikle dig og være en del af et hold med ambitioner og fællesskab. Det er ønskeligt, at alle deltager i turneringer, eller at man har lyst til at prøve det. Turneringskalenderen findes længere nede på siden. På Empire: Træner vi avanceret showdance-teknik og koreografi. Arbejder vi med performance, udstråling og præcision. Skaber vi et stærkt sammenhold med plads til humor, hygge og støtte. Motiverer vi hinanden og har det sjovt, mens vi udvikler os. Empire er for dansere, der elsker at danse og optræde, og som vil være en del af et team, der løfter hinanden. Vi glæder os til endnu en sæson med sved på panden, smil på læben og mange gode øjeblikke.

Tekniktræning
Torsdag kl. 19:05–20:10 med træner Malou. Teknikholdet fokuserer på at finpudse tekniske færdigheder, avancerede spring, drejninger og tricks samt styrkeøvelser for de små muskler, som skal mindske skaderisikoen. Empire og Control træner sammen på denne time. Teknikholdet er inkluderet i prisen.', price = '5.825 kr. for hele sæsonen', years = '2008–2013', day_time = 'Onsdag kl. 17:40–18:40 (60 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2026/04/1X4A7047-Edit-c-633x1024.jpg') where school_id = sid and name = 'Empire';
update team set description = 'Mini Magic – for de små dansere med store ambitioner! Et dansehold for mini-børn, der allerede har konkurreret og er klar til at tage det næste skridt. Holdet er for øvede dansere med mindst to konkurrencesæsoner bag sig.

Mini Magic – For de små dansere med store ambitioner!
Mini Magic er et dansehold for mini-børn, der allerede har konkurreret og er klar til at tage det næste skridt. Holdet henvender sig til øvede dansere med mindst to konkurrencesæsoner bag sig, som gerne vil udvikle sig yderligere inden for showdance. Der stilles lidt højere krav – men med glæde, sammenhold og motivation. Holdet er for dem, der vil det lidt mere, både teknisk og kreativt. På holdet arbejder vi med: Forfining af showdance-teknik med fokus på detaljer og performance. Udfordrende koreografier og forberedelse til konkurrencer. Udtryk, præcision og scenetække. Fællesskab, selvtillid og danseglæde. Deltagelse i konkurrencer er en fast del af holdet, og man forventes at deltage i alle turneringer. Konkurrencekalenderen findes længere nede på siden. Vi glæder os til at tage dansen til næste niveau sammen med jer og til en ny sæson med energi, udvikling og oplevelser på scenen.', price = '4.250 kr. for hele sæsonen', years = '2017–2020', day_time = 'Torsdag kl. 15:45–16:30 (45 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2026/04/1X4A0821-c-448x1024.jpg') where school_id = sid and name = 'Mini Magic';
update team set description = 'Hop, rul & flyv – mini style! Holdet er for de unge Mini Børn-dansere, der elsker at lave tricks og spring. Der arbejdes med grundlæggende springteknik og nye bevægelser – uanset om du allerede kan lave en vejrmølle eller aldrig har prøvet før.

Hop, Rul & Flyv – Mini Style!
Holdet er for de unge Mini Børn-dansere, der kan lide at lave tricks og spring. Der arbejdes med grundlæggende springteknik og nye bevægelser, uanset om man allerede kan lave en vejrmølle eller aldrig har prøvet før. Vi bruger airtrack og øver rul, vejrmøller, back over og andre gulvtricks. Der trænes også styrke, især i armene, så deltagerne bliver mere trygge og modige – også hvis de er lidt usikre i starten. Holdet er for alle niveauer. Målet er at have det sjovt, blive stærkere og lære nye ting sammen.', price = '2.250 kr. for hel sæson, eller 1.550 kr. for halv sæson (august–december)', years = '2017–2020', day_time = 'Torsdag kl. 16:35–17:20 (45 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2025/04/DSC09080-scaled.jpg') where school_id = sid and name = 'Spring & Tumbling Mini';
update team set description = 'Smidighed & Acro – for alle niveauer. Holdet er for alle, der vil arbejde med smidighed, kropskontrol og akrobatiske elementer, uanset om man er nybegynder eller øvet.', price = '2.250 kr. for hel sæson, eller 1.550 kr. for halv sæson (august–december)', years = '2013–2016', day_time = 'Torsdag kl. 17:25–18:10 (45 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2025/04/DSC09446-scaled.jpg') where school_id = sid and name = 'Smidighed & Acro';
update team set description = 'Trick- og springteknik for øvede og elite (junior & voksne). Holdet er for dem, der har et solidt fundament og vil videre med spring, tricks og akrobatik.', price = '2.250 kr. for hel sæson, eller 1.550 kr. for halv sæson (august–december)', years = 'Fra årgang 2013', day_time = 'Torsdag kl. 18:15–19:00 (45 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2024/05/DSC01255-scaled.jpg') where school_id = sid and name = 'Spring & Tumbling Junior & Voksen';
update team set description = 'MGP-Stjerner – dans og bevægelse for de mindste. Holdet er for dansere fra 3 år og op til skolestart. Der danses til kendte, sjove MGP-sange med fokus på glæde, tryghed og leg gennem dans.', price = '1.750 kr. for hel sæson, eller 975 kr. for halv sæson (august–december)', years = '3 år til skolestart', day_time = 'Torsdag kl. 16:35–17:20 (45 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2025/04/DSC_2324.jpg') where school_id = sid and name = 'Danse Stjerner';
update team set description = 'Mini ballerinaer på vej. Holdet er for de yngste dansere, der drømmer om at udvikle elegance og ynde. Børnene bevæger sig til smuk, klassisk musik i et trygt og fantasifuldt rum.', price = '2.250 kr. for hel sæson, eller 1.550 kr. for halv sæson (august–december)', years = '2017–2022', day_time = 'Torsdag kl. 17:25–18:10 (45 min)', closed = false, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2025/04/DSC09852-scaled.jpg') where school_id = sid and name = 'Ballet Mini';
update team set description = 'No Addiction er et talentfuldt dansehold bestående af dygtige dansere i alderen 17 og op. Et energisk og dedikeret hold, hvor vejen til succes går gennem hårdt arbejde og mange timers træning.

No Addiction – et talentfuldt dansehold bestående af dygtige dansere i alderen 17 og op
Holdet består af unge, dygtige dansere, og der er krav om at være 17 år eller ældre. Vejen til succes går gennem hårdt arbejde og mange timers træning.

Optagelse
Man skal bestå en audition på LL Dance Studio, hvor talent, udtryksevne og tekniske færdigheder vurderes. Vi leder efter nye talenter og vil skabe et fællesskab af dansere, der deler lidenskab og visioner. Krav for No Addiction og regelhæfte findes som PDF på siden.

Træning
Holdet træner én gang om måneden i 4 timer (se kalender) med intensivt fokus på koreografi, performance og udvikling. For at fastholde og løbende forbedre niveauet skal alle dansere samtidig deltage på et tilvalgshold én gang om ugen – det er både et krav og et ønske.', price = '6.650 kr. for hele sæsonen', years = '2007 og ældre (17 år+)', day_time = 'Træner 1 gang om måneden i 4 timer (se kalender)', closed = true, cover_url = coalesce(cover_url, 'https://lldancestudio.dk/wp-content/uploads/2024/05/DSC01599-576x1024.jpg') where school_id = sid and name = 'No Addiction';
